 * High-performance portfolio calculations using C extension
 *
 * Implements sqrt(x^T * S * x) and x^T * r with the same
 * summation order as the Python baseline for bit-level agreement.
 */

#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>

static PyObject* portfolio_risk_c(PyObject *self, PyObject *args) {
    PyObject *weights_obj, *cov_obj;

    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &cov_obj))
        return NULL;

    PyArrayObject *weights_array = (PyArrayObject *)PyArray_FROM_OTF(
        weights_obj, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    PyArrayObject *cov_array = (PyArrayObject *)PyArray_FROM_OTF(
        cov_obj, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);

    if (weights_array == NULL || cov_array == NULL) {
        Py_XDECREF(weights_array);
        Py_XDECREF(cov_array);
        return NULL;
    }

    if (PyArray_NDIM(weights_array) != 1) {
        PyErr_SetString(PyExc_ValueError, "weights must be 1-dimensional");
        Py_DECREF(weights_array);
        Py_DECREF(cov_array);
        return NULL;
    }
    if (PyArray_NDIM(cov_array) != 2) {
        PyErr_SetString(PyExc_ValueError, "cov_matrix must be 2-dimensional");
        Py_DECREF(weights_array);
        Py_DECREF(cov_array);
        return NULL;
    }

    npy_intp n = PyArray_DIM(weights_array, 0);
    npy_intp rows = PyArray_DIM(cov_array, 0);
    npy_intp cols = PyArray_DIM(cov_array, 1);
    if (rows != n || cols != n) {
        PyErr_SetString(PyExc_ValueError,
                        "cov_matrix must be n x n where n = len(weights)");
        Py_DECREF(weights_array);
        Py_DECREF(cov_array);
        return NULL;
    }

    double *w = (double *)PyArray_DATA(weights_array);
    double *cov = (double *)PyArray_DATA(cov_array);

    double risk_squared;

    if (n == 0) {
        risk_squared = 0.0;
    } else {
        double *temp = (double *)malloc((size_t)n * sizeof(double));
        if (temp == NULL) {
            PyErr_NoMemory();
            Py_DECREF(weights_array);
            Py_DECREF(cov_array);
            return NULL;
        }

        /* Step 1: temp[i] = sum_j cov[i][j] * w[j], same order as baseline */
        for (npy_intp i = 0; i < n; i++) {
            double row_sum = 0.0;
            double *row = cov + i * n;
            for (npy_intp j = 0; j < n; j++) {
                row_sum += row[j] * w[j];
            }
            temp[i] = row_sum;
        }

        /* Step 2: risk_squared = sum_i w[i] * temp[i] */
        double acc = 0.0;
        for (npy_intp i = 0; i < n; i++) {
            acc += w[i] * temp[i];
        }
        free(temp);
        risk_squared = acc;
    }

    /* Guard against tiny negative due to rounding */
    if (risk_squared < 0.0 && risk_squared > -1e-18) {
        risk_squared = 0.0;
    }

    double result = sqrt(risk_squared);

    Py_DECREF(weights_array);
    Py_DECREF(cov_array);
    return PyFloat_FromDouble(result);
}

