{"content":"/*
 * High-performance portfolio calculations using C extension
 *
 * risk: sqrt(x^T * S * x) exploiting symmetry of S:
 *   risk^2 = sum_i S_ii w_i^2 + 2*sum_{i<j} S_ij w_i w_j
 * Only the upper triangle is touched, halving work and (for
 * list inputs) halving Python-object accesses. Reordering error
 * is ~1e-16, far below the 1e-10 tolerance.
 */

#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>

static PyObject* portfolio_risk_c(PyObject *self, PyObject *args) {
    PyObject *weights_obj, *cov_obj;

    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &cov_obj))
        return NULL;

    PyArrayObject *w_arr = (PyArrayObject *)PyArray_FROM_OTF(
        weights_obj, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    if (w_arr == NULL)
        return NULL;
    if (PyArray_NDIM(w_arr) != 1) {
        Py_DECREF(w_arr);
        PyErr_SetString(PyExc_ValueError, "weights must be 1-D");
        return NULL;
    }
    npy_intp n = PyArray_DIM(w_arr, 0);
    double *w = (double *)PyArray_DATA(w_arr);

    double risk_squared = 0.0;

    if (PyList_Check(cov_obj)) {
        /* Fast path: cov is a list of lists (as produced by
         * generate_test_data). Touch only the upper triangle,
         * no 512 MB temporary copy. */
        if (PyList_Size(cov_obj) != n) {
            Py_DECREF(w_arr);
            PyErr_SetString(PyExc_ValueError,
                            "cov rows must match weights length");
            return NULL;
        }
        for (npy_intp i = 0; i < n; i++) {
            PyObject *row = PyList_GetItem(cov_obj, i); /* borrowed */
            if (!PyList_Check(row) || PyList_Size(row) != n) {
                Py_DECREF(w_arr);
                PyErr_SetString(PyExc_ValueError,
                                "cov must be an n x n list of lists");
                return NULL;
            }
            double wi = w[i];
            double sii = PyFloat_AsDouble(PyList_GetItem(row, i));
            if (PyErr_Occurred()) {
                Py_DECREF(w_arr);
                return NULL;
            }
            risk_squared += sii * wi * wi;
            double wi2 = 2.0 * wi;
            for (npy_intp j = i + 1; j < n; j++) {
                double sij = PyFloat_AsDouble(PyList_GetItem(row, j));
                if (PyErr_Occurred()) {
                    Py_DECREF(w_arr);
                    return NULL;
                }
                risk_squared += wi2 * w[j] * sij;
            }
        }
        Py_DECREF(w_arr);
        return PyFloat_FromDouble(sqrt(risk_squared));
    }

    /* Generic / ndarray path: zero-copy contiguous double view. */
    PyArrayObject *c_arr = (PyArrayObject *)PyArray_FROM_OTF(
        cov_obj, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    if (c_arr == NULL) {
        Py_DECREF(w_arr);
        return NULL;
    }
    if (PyArray_NDIM(c_arr) != 2 ||
        PyArray_DIM(c_arr, 0) != n || PyArray_DIM(c_arr, 1) != n) {
        Py_DECREF(w_arr);
        Py_DECREF(c_arr);
        PyErr_SetString(PyExc_ValueError, "cov must be an n x n matrix");
        return NULL;
    }
    double *c = (double *)PyArray_DATA(c_arr);
    for (npy_intp i = 0; i < n; i++) {
        double wi = w[i];
        double *row = c + i * n;
        risk_squared += row[i] * wi * wi;
        double wi2 = 2.0 * wi;
        for (npy_intp j = i + 1; j < n; j++) {
            risk_squared += wi2 * w[j] * row[j];
        }
    }
    Py_DECREF(w_arr);
    Py_DECREF(c_arr);
    return PyFloat_FromDouble(sqrt(risk_squared));
}

static PyObject* portfolio_return_c(PyObject *self, PyObject *args) {
    PyObject *weights_obj, *returns_obj;

    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &returns_obj))
        return NULL;

    PyArrayObject *w_arr = (PyArrayObject *)PyArray_FROM_OTF(
        weights_obj, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    PyArrayObject *r_arr = (PyArrayObject *)PyArray_FROM_OTF(
        returns_obj, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    if (w_arr == NULL || r_arr == NULL) {
        Py_XDECREF(w_arr);
        Py_XDECREF(r_arr);
        return NULL;
    }
    if (PyArray_NDIM(w_arr) != 1 || PyArray_NDIM(r_arr) != 1 ||
        PyArray_DIM(w_arr, 0) != PyArray_DIM(r_arr, 0)) {
        Py_DECREF(w_arr);
        Py_DECREF(r_arr);
        PyErr_SetString(PyExc_ValueError,
                        "weights and returns must be 1-D of equal length");
        return NULL;
    }
    npy_intp n = PyArray_DIM(w_arr, 0);
    double *w = (double *)PyArray_DATA(w_arr);
    double *r = (double *)PyArray_DATA(r_arr);

    double total = 0.0;
    npy_intp i = 0;
    /* Unrolled accumulation in order (4-way) for speed. */
    npy_intp n4 = n & ~(npy_intp)3;
    for (; i < n4; i += 4) {
        total += w[i] * r[i] + w[i + 1] * r[i + 1] +
                 w[i + 2] * r[i + 2] + w[i + 3] * r[i + 3];
    }
    for (; i < n; i++) {
        total += w[i] * r[i];
    }

    Py_DECREF(w_arr);
    Py_DECREF(r_arr);
    return PyFloat_FromDouble(total);
}

